const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const toast = $('#toast');
let toastTimer;
const boundPosts = new WeakSet();
function notify(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3000)}
const storage={get(k,fallback){try{const v=localStorage.getItem('shelves:'+k);return v===null?fallback:JSON.parse(v)}catch{return fallback}},set(k,v){try{localStorage.setItem('shelves:'+k,JSON.stringify(v))}catch{notify('Storage is unavailable. Your changes may not survive a reload.')}}};
function esc(value=''){return String(value).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}
function appDialog({title,description='',label='Save',placeholder='',value='',input=true,multiline=false,kind='text'}={}){
 return new Promise(resolve=>{const wrap=document.createElement('div');wrap.className='app-dialog-backdrop';wrap.innerHTML=`<section class="app-dialog" role="dialog" aria-modal="true" aria-labelledby="appDialogTitle"><button class="app-dialog-close" type="button" aria-label="Close dialog">×</button><span class="section-kicker">A LITTLE SHELVES MOMENT</span><h2 id="appDialogTitle">${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}<form novalidate>${input?(multiline?`<textarea class="app-dialog-input" maxlength="500" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input class="app-dialog-input" type="${kind}" value="${esc(value)}" placeholder="${esc(placeholder)}" maxlength="80" autocomplete="off">`):''}<div class="app-dialog-actions"><button type="button" class="outline-btn dialog-cancel">Cancel</button><button type="submit" class="primary-btn">${esc(label)}</button></div></form></section>`;document.body.append(wrap);const field=$('.app-dialog-input',wrap);let escKey;const finish=result=>{if(escKey)document.removeEventListener('keydown',escKey);wrap.remove();resolve(result)};$('.app-dialog-close',wrap).onclick=()=>finish(null);$('.dialog-cancel',wrap).onclick=()=>finish(null);wrap.addEventListener('click',e=>{if(e.target===wrap)finish(null)});wrap.querySelector('form').onsubmit=e=>{e.preventDefault();const val=field?.value.trim()??true;if(input&&!val){field?.focus();return}finish(val)};escKey=function(e){if(e.key==='Escape'&&document.body.contains(wrap))finish(null)};document.addEventListener('keydown',escKey);field?.focus()})}
function persistInteractions(){const state={};$$('.post-card').forEach((card,i)=>{const id=card.dataset.postId||(card.dataset.postId=`seed-${card.dataset.author||'reader'}-${card.dataset.kind||'note'}`);card.dataset.postId=id;state[id]={liked:$('.like-btn',card)?.classList.contains('liked')||false,saved:$('.bookmark-btn',card)?.classList.contains('saved')||false,likes:$('.like-btn b',card)?.textContent||'0'}});storage.set('interactions',state)}
const modal = $('#modalBackdrop');
function openComposer(type='thought'){modal.hidden=false;$('#postType').value=type;$('#modalTitle').textContent=type==='review'?'Write a little review':type==='quote'?'Save a line you love':type==='progress'?'Mark your reading progress':'Share a little thought';$('#postText').focus()}
function closeComposer(){modal.hidden=true}
$('#openComposer').addEventListener('click',()=>openComposer());
$('#composePrompt').addEventListener('click',()=>openComposer());
$('#mobileCompose').addEventListener('click',()=>openComposer());
$('#closeModal').addEventListener('click',closeComposer);
modal.addEventListener('click',e=>{if(e.target===modal)closeComposer()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeComposer();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchInput').focus()}});
$$('[data-compose]').forEach(b=>b.addEventListener('click',()=>openComposer(b.dataset.compose)));
$('#postType').addEventListener('change',e=>{$('#modalTitle').textContent=({review:'Write a little review',quote:'Save a line you love',progress:'Mark your reading progress',thought:'Share a little thought'})[e.target.value]});
$('#postForm').addEventListener('submit',e=>{
 e.preventDefault();const text=$('#postText').value.trim();if(!text){const help=$('#postTextHelp');if(help)help.textContent='Add a note before sharing it.';$('#postText').focus();return;}
 const book=$('#postBook').value.trim();const type=$('#postType').value;
 const card=document.createElement('article');card.className='post-card';card.dataset.kind=type;
 const now=new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});
 const safeText=text.replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 const safeBook=book.replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 card.innerHTML=`<div class="post-head"><span class="avatar avatar-you">M</span><div class="post-author"><strong>Morgan Ellis</strong><small>@morgan.reads · just now (${now})</small></div><button class="more-button" aria-label="More post options">···</button></div><p class="post-copy">${safeText}</p>${safeBook?`<div class="post-book-chip">📖 &nbsp; Reading alongside: <strong>${safeBook}</strong></div>`:''}<div class="post-actions"><button class="like-btn"><span>♡</span> <b>0</b> appreciations</button><button class="comment-btn">○ <b>0</b> notes</button><button class="share-btn">↗ <span>Share</span></button><button class="bookmark-btn" aria-label="Save post">♧</button></div>`;
 $('#feedList').prepend(card);card.dataset.postId=`post-${Date.now()}`;bindPost(card);const savedPosts=storage.get('posts',[]);savedPosts.unshift(card.outerHTML);storage.set('posts',savedPosts.slice(0,30));persistInteractions();$('#postText').value='';$('#postBook').value='';closeComposer();notify('Your note has been shared with your circle.');card.scrollIntoView({behavior:'smooth',block:'center'});
});
function bindPost(card){
 if(boundPosts.has(card))return;boundPosts.add(card);
 const like=$('.like-btn',card);like?.addEventListener('click',()=>{const liked=like.classList.toggle('liked');like.querySelector('span').textContent=liked?'♥':'♡';const count=like.querySelector('b');count.textContent=Number(count.textContent)+(liked?1:-1);persistInteractions();});
 $('.bookmark-btn',card)?.addEventListener('click',e=>{const b=e.currentTarget;b.classList.toggle('saved');persistInteractions();notify(b.classList.contains('saved')?'Saved to your reading journal.':'Removed from saved notes.')});
 $('.share-btn',card)?.addEventListener('click',()=>{if(navigator.clipboard?.writeText){navigator.clipboard.writeText(location.href).then(()=>notify('Page link copied to your clipboard.')).catch(()=>notify('Ready to share with your reading circle.'))}else notify('Ready to share with your reading circle.')});
 $('.comment-btn',card)?.addEventListener('click',async()=>{let comments=storage.get('comments',{});const id=card.dataset.postId||card.querySelector('.post-author strong')?.textContent||'post';const existing=comments[id]||[];const entry=await appDialog({title:'Leave a little note',description:existing.length?`${existing.length} note${existing.length===1?'':'s'} in this conversation. Add a kind thought of your own.`:'Start a thoughtful conversation. Keep it kind and bookish.',label:'Add note',placeholder:'What would you like to say?',multiline:true});if(entry){comments[id]=[...existing,{text:entry,author:'Morgan',date:new Date().toISOString()}];storage.set('comments',comments);const b=$('.comment-btn b',card);if(b)b.textContent=Number(b.textContent||0)+1;notify('Your note has been added to the conversation.')}});
 $('.more-button',card)?.addEventListener('click',async()=>{const choice=await appDialog({title:'A little post care',description:'Type “save” to bookmark this post, or “report” if something feels wrong.',label:'Continue',placeholder:'save or report'});if(!choice)return;if(choice.toLowerCase()==='save'){$('.bookmark-btn',card)?.click()}else if(choice.toLowerCase()==='report')notify('Thanks for looking after the reading room. This post has been flagged in this demo.');else notify('Choose “save” or “report” to continue.');});
}
$$('.post-card').forEach(bindPost);
$$('.add-book').forEach(bindBook);
$$('.follow-btn').forEach(b=>{const person=b.closest('.person-row')?.querySelector('strong')?.textContent||'reader';if(storage.get('following',[]).includes(person)){b.classList.add('following');b.textContent='Following'}b.addEventListener('click',()=>{const on=b.classList.toggle('following');b.textContent=on?'Following':'Follow';const list=storage.get('following',[]);storage.set('following',on?[...new Set([...list,person])]:list.filter(x=>x!==person));notify(on?'Added to your reading circle.':'Removed from your reading circle.')})});
$('#notificationsBtn').addEventListener('click',async()=>{const choice=await appDialog({title:'Your reading post',description:'You’re all caught up. Want to check your saved notes or visit your journal?',label:'Open journal',input:false});if(choice!==null)showView('journal')});
async function setReadingGoal(){const current=storage.get('goal',30);const n=await appDialog({title:'Plant a reading goal',description:'Choose a number that feels inspiring, not intimidating.',label:'Save my goal',placeholder:'Books this year',value:String(current),kind:'number'});if(n!==null&&Number(n)>0&&Number(n)<=500){storage.set('goal',Math.round(Number(n)));$$('#booksRead,#profileBooks').forEach(el=>el.nextElementSibling&&(el.nextElementSibling.textContent=`of ${Math.round(Number(n))} books read this year`));$('.goal-percent')&&($('.goal-percent').textContent=`${Math.min(100,Math.round(18/Number(n)*100))}%`);$('.goal-track span')&&($('.goal-track span').style.width=`${Math.min(100,18/Number(n)*100)}%`);notify(`Your new goal is ${Math.round(Number(n))} books. One page at a time.`)}else if(n!==null)notify('Choose a goal between 1 and 500 books.');}
$('#startReading').addEventListener('click',setReadingGoal);
$('#addShelf').addEventListener('click',async()=>{const name=await appDialog({title:'Make a new shelf',description:'Give this little corner of your library a name.',label:'Create shelf',placeholder:'e.g. Books for rainy days'});if(name){const shelves=storage.get('customShelves',[]);if(shelves.some(x=>x.toLowerCase()===name.toLowerCase())){notify('You already have a shelf with that name.');return}shelves.push(name);storage.set('customShelves',shelves);addShelfButton(name);notify(`Your “${name}” shelf is ready.`)}});
function addShelfButton(name){const nav=$('.shelf-nav');if(!nav||$$('.shelf-link',nav).some(b=>b.dataset.shelf===name))return;const btn=document.createElement('button');btn.className='shelf-link';btn.dataset.shelf=name;btn.innerHTML=`<i class="shelf-dot blue"></i> ${esc(name)} <span>0</span>`;btn.addEventListener('click',()=>showView('shelves',name));nav.append(btn)}
storage.get('customShelves',[]).forEach(addShelfButton);
$$('.shelf-link').forEach(b=>b.addEventListener('click',()=>showView('shelves',b.dataset.shelf||b.textContent.trim())));
$$('.filter-btn').forEach(b=>b.addEventListener('click',()=>{$$('.filter-btn').forEach(x=>x.classList.toggle('active',x===b));const f=b.dataset.filter;$$('#feedList .post-card').forEach(card=>card.hidden=f==='reviews'?card.dataset.kind!=='review':f==='following'?card.dataset.author==='sam':false)}));
const titles={home:'Your reading nook',discover:'Find your next favorite',shelves:'Your personal library',clubs:'Better stories, together',journal:'Notes worth keeping',profile:'Your little reading life'};
function showView(view, shelfName=''){
 $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$$('.mobile-nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 $('#pageTitle').textContent=view==='shelves'&&shelfName?shelfName:titles[view]||titles.home;
 const root=$('#viewRoot');
 if(view==='shelves'||view==='discover'){location.hash=view;renderLibrary(view,shelfName);return}
 if(view==='home'){location.hash='';root.innerHTML=homeMarkup;$('#feedList').innerHTML=feedMarkup;storage.get('posts',[]).slice().reverse().forEach(html=>{const t=document.createElement('template');t.innerHTML=html.trim();const card=t.content.firstElementChild;if(card&&card.classList.contains('post-card'))$('#feedList',root).prepend(card)});$$('.post-card',root).forEach((c,i)=>{if(!c.dataset.bound){bindPost(c);c.dataset.bound='1'}});$$('.add-book',root).forEach(bindBook);$$('.filter-btn',root).forEach(b=>b.addEventListener('click',()=>{$$('.filter-btn',root).forEach(x=>x.classList.toggle('active',x===b));$$('.post-card',root).forEach(c=>c.hidden=b.dataset.filter==='reviews'?c.dataset.kind!=='review':b.dataset.filter==='following'?c.dataset.author==='sam':false)}));$('#composePrompt',root).addEventListener('click',()=>openComposer());$('#openComposer',root).addEventListener('click',()=>openComposer());$('#startReading',root).addEventListener('click',setReadingGoal);$$('[data-compose]',root).forEach(b=>b.addEventListener('click',()=>openComposer(b.dataset.compose)));$('#loadMore',root)?.addEventListener('click',()=>notify('You’re all caught up. Take a breath, then turn another page.'));return}
 location.hash=view;const views={
 discover:`<section class="view-panel"><span class="section-kicker">FOLLOW YOUR CURIOSITY</span><h2>Something good is waiting.</h2><p class="view-intro">A few paths to your next can’t-put-it-down book.</p><div class="book-grid">${bookTile('cover-garden','The Secret Garden','Frances Hodgson Burnett','Classic')}${bookTile('cover-octopus','Remarkably Bright Creatures','Shelby Van Pelt','Fiction')}${bookTile('cover-forest','The Overstory','Richard Powers','Literary')}${bookTile('cover-moon','Braiding Sweetgrass','Robin Wall Kimmerer','Nature')}${bookTile('cover-coral','Small Things Like These','Claire Keegan','Novella')}${bookTile('cover-blue','Piranesi','Susanna Clarke','Fantasy')}</div></section><section class="view-panel"><span class="section-kicker">COMMUNITY PROMPT</span><h2>What book feels like home?</h2><p class="view-intro">Share a comfort read with your circle and help someone find their next familiar place.</p><button class="primary-btn" onclick="openComposer('thought')">Answer the prompt ↗</button></section>`,
 shelves:`<section class="view-panel"><span class="section-kicker">A LIBRARY THAT'S ALL YOURS</span><h2>${esc(shelfName||'Your shelves')}</h2><p class="view-intro">Keep track of the stories you've met, and the ones still calling your name.</p><div class="book-grid">${bookTile('cover-garden','The Secret Garden','Frances Hodgson Burnett','Want to read')}${bookTile('cover-octopus','Remarkably Bright Creatures','Shelby Van Pelt','Currently reading')}${bookTile('cover-forest','The Overstory','Richard Powers','Currently reading')}${bookTile('cover-moon','Braiding Sweetgrass','Robin Wall Kimmerer','Finished')}${bookTile('cover-coral','Small Things Like These','Claire Keegan','Finished')}${bookTile('cover-blue','Piranesi','Susanna Clarke','Want to read')}</div></section>`,
 clubs:`<section class="view-panel"><span class="section-kicker">FIND YOUR PEOPLE</span><h2>There's room in the circle.</h2><p class="view-intro">Small groups, good questions, and absolutely no pressure to finish by Tuesday.</p>${clubRow('❧','The Slow Readers','126 members · one chapter a week','sage')}${clubRow('☾','After Hours Fiction','84 members · strange worlds after dark','moon')}${clubRow('✿','Poetry & Other Small Things','52 members · a poem every Sunday','coral')}${clubRow('♧','The Nature Shelf','91 members · books rooted in the wild','sage')}${storage.get('customClubs',[]).map(name=>clubRow('✦',name,'Your new reading circle · just getting started','coral')).join('')}<button class="primary-btn" id="startClub">Start a book circle ↗</button></section>`,
 journal:`<section class="view-panel"><span class="section-kicker">YOUR READING JOURNAL</span><h2>Little things worth remembering.</h2><p class="view-intro">Quotes, feelings, and thoughts from the books that stay with you.</p><div class="journal-entry"><div class="journal-date">OCT 12<br>MONDAY</div><div><h3>A sentence to keep</h3><p>“There is no exquisite beauty without some strangeness in the proportion.” — Edgar Allan Poe</p></div></div><div class="journal-entry"><div class="journal-date">OCT 08<br>THURSDAY</div><div><h3>Reading by the window</h3><p>Twenty pages and a cup of tea. A small pocket of quiet before the day began.</p></div></div><div class="journal-entry"><div class="journal-date">OCT 02<br>FRIDAY</div><div><h3>Books that feel like weather</h3><p>Some stories don't just tell you a place. They change the atmosphere around you.</p></div></div><button class="primary-btn" id="newJournal">Add a journal note ↗</button></section>`,
 profile:`<section class="view-panel"><div class="profile-hero"><span class="avatar avatar-you">M</span><div><span class="section-kicker">YOUR READING LIFE</span><h2>Morgan Ellis</h2><p>@morgan.reads · collecting stories and quiet mornings</p><div class="profile-stats"><span><b>128</b> followers</span><span><b>86</b> following</span><span><b>28</b> books finished</span></div></div></div><h2>Your year between the pages</h2><p class="view-intro">A little progress adds up to a lot of worlds visited.</p><div class="goal-number"><strong id="profileBooks">18</strong><span>of 30 books read this year</span></div><div class="goal-track"><span></span></div><div class="book-grid" style="margin-top:18px">${bookTile('cover-garden','The Secret Garden','Frances Hodgson Burnett','Want to read')}${bookTile('cover-octopus','Remarkably Bright Creatures','Shelby Van Pelt','Currently reading')}${bookTile('cover-forest','The Overstory','Richard Powers','Currently reading')}</div></section>`
 };
 root.innerHTML=views[view]||views.home;
 $$('.add-book',root).forEach(bindBook);
 $('#startClub')?.addEventListener('click',async()=>{const name=await appDialog({title:'Start a book circle',description:'Choose a name for the kind of reading you want to do together.',label:'Create circle',placeholder:'e.g. Sunday Chapter Club'});if(name){const clubs=storage.get('customClubs',[]);if(clubs.some(x=>x.toLowerCase()===name.toLowerCase())){notify('A circle with that name already exists.');return}clubs.push(name);storage.set('customClubs',clubs);showView('clubs');notify(`“${name}” is ready for its first readers.`)}});
 $('#newJournal')?.addEventListener('click',()=>openComposer('thought'));
}
function bindBook(b){if(b.dataset.bookBound&&b.dataset.bookBound==='live')return;b.dataset.bookBound='live';const title=b.dataset.book||b.closest('.book-tile')?.querySelector('h3')?.textContent||'Book';const statuses=storage.get('bookStatuses',{});if(statuses[title]){b.classList.add('added');b.textContent='✓ On your shelf'}b.addEventListener('click',()=>{const on=b.classList.toggle('added');const next=storage.get('bookStatuses',{});if(on)next[title]=next[title]||'Want to read';else delete next[title];storage.set('bookStatuses',next);$$(`[data-book="${CSS.escape(title)}"]`).forEach(other=>{other.classList.toggle('added',on);other.textContent=on?'✓ On your shelf':'＋ Add to shelf'});updateShelfCounts();notify(on?`“${title}” added to your Want to read shelf.`:`“${title}” removed from your shelf.`)})}
function bookTile(cover,title,author,tag){const safe=title.replace(/'/g,"\\'");return `<article class="book-tile"><div class="large-cover ${cover}"><span class="cover-small">A SHELVES PICK</span><strong>${title.toUpperCase()}</strong><span class="cover-flower">✿</span><small>${author.toUpperCase()}</small></div><h3>${title}</h3><p>${author}</p><span class="tag tag-sage">${tag.toUpperCase()}</span><br><button class="outline-btn add-book" data-book="${title}">＋ Add to shelf</button></article>`}
function clubRow(icon,title,desc,color){const joined=storage.get('joinedClubs',[]).includes(title);return `<div class="club-feature"><div class="club-icon club-${color}">${icon}</div><div><h3>${title}</h3><p>${desc}</p></div><button class="outline-btn join-club">${joined?'✓ Joined':'Join circle ↗'}</button></div>`}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
document.addEventListener('click',e=>{if(e.target.matches('.join-club')){const joined=!e.target.textContent.startsWith('✓');e.target.textContent=joined?'✓ Joined':'Join circle ↗';const name=e.target.closest('.club-feature')?.querySelector('h3')?.textContent||'book circle';const list=storage.get('joinedClubs',[]);storage.set('joinedClubs',joined?[...new Set([...list,name])]:list.filter(x=>x!==name));notify(joined?'Welcome to the circle.':'You left the circle.')}});
$('#refreshPeople').addEventListener('click',()=>{const card=$('.people-card');const rows=$$('.person-row',card);if(rows.length>1)card.insertBefore(rows[rows.length-1],rows[0]);notify('A fresh reader suggestion is waiting at the top.');});
$('#loadMore').addEventListener('click',()=>notify('You’re all caught up. Take a breath, then turn another page.'));
$('#searchInput').addEventListener('input',e=>{const q=e.target.value.toLowerCase().trim();const cards=$$('.post-card');let found=0;cards.forEach(c=>{const match=!q||c.textContent.toLowerCase().includes(q);c.hidden=!match;if(match)found++});$$('.book-tile').forEach(c=>{c.hidden=!!q&&!c.textContent.toLowerCase().includes(q)});if(q&&found===0&&!$$('.book-tile:not([hidden])').length)notify('No matches yet. Try a title, author, or reader.');});
$('#searchInput').addEventListener('keydown',e=>{if(e.key==='Escape'){e.target.value='';e.target.dispatchEvent(new Event('input'));e.target.blur()}});
$('#postText').addEventListener('input',e=>{const help=$('#postTextHelp');if(help)help.textContent=`${e.target.value.length}/1,200 characters`;});
const homeMarkup=$('#viewRoot').innerHTML;
const feedMarkup=$('#feedList').innerHTML;

// Restore reader-created notes and interaction state for this browser.
(function restoreLocalState(){
 const feed=$('#feedList');const posts=storage.get('posts',[]);posts.slice().reverse().forEach(html=>{const template=document.createElement('template');template.innerHTML=html.trim();const card=template.content.firstElementChild;if(card&&card.classList.contains('post-card')){feed.prepend(card);bindPost(card)}});
 const states=storage.get('interactions',{});$$('.post-card').forEach((card,i)=>{const id=card.dataset.postId||(card.dataset.postId=`seed-${card.dataset.author||'reader'}-${card.dataset.kind||'note'}`);card.dataset.postId=id;const state=states[id];if(!state)return;const like=$('.like-btn',card);if(like){like.classList.toggle('liked',!!state.liked);const icon=$('span',like);if(icon)icon.textContent=state.liked?'♥':'♡';const count=$('b',like);if(count)count.textContent=state.likes??count.textContent}const save=$('.bookmark-btn',card);if(save)save.classList.toggle('saved',!!state.saved)});
 const goal=storage.get('goal',30);const pct=Math.min(100,Math.round(18/goal*100));$('.goal-percent')&&($('.goal-percent').textContent=`${pct}%`);$('.goal-track span')&&($('.goal-track span').style.width=`${pct}%`);$$('#booksRead,#profileBooks').forEach(el=>{if(el.nextElementSibling)el.nextElementSibling.textContent=`of ${goal} books`});
})();
